package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
)

type fastSource struct {
	text string
	used bool
}

func (s *fastSource) Read([]byte) (int, error) {
	return 0, errors.New("fallback Read should not run")
}

func (s *fastSource) WriteTo(dst io.Writer) (int64, error) {
	s.used = true
	n, err := io.WriteString(dst, s.text)
	return int64(n), err
}

func main() {
	source := &fastSource{text: "fast path"}
	var destination bytes.Buffer
	count, err := io.Copy(&destination, source)
	if err != nil {
		panic(err)
	}
	fmt.Println(source.used, count, destination.String())
}
