```go
package main

import (
	"bytes"
	"fmt"
	"io"
	"strings"
)

type readOnly struct{ io.Reader }
type writeOnly struct{ io.Writer }

func main() {
	var header bytes.Buffer
	n, err := io.CopyN(&header, strings.NewReader("HEADbody"), 4)
	if err != nil {
		panic(err)
	}
	fmt.Println(n, header.String())

	var body bytes.Buffer
	src := readOnly{Reader: strings.NewReader("payload")}
	dst := writeOnly{Writer: &body}
	n, err = io.CopyBuffer(dst, src, make([]byte, 3))
	if err != nil {
		panic(err)
	}
	fmt.Println(n, body.String())
}
